import dorm2r = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const A = new Float64Array( 9 );
	const tau = new Float64Array( 3 );
	const C = new Float64Array( 9 );
	const work = new Float64Array( 3 );

	dorm2r( 'row-major', 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const A = new Float64Array( 9 );
	const tau = new Float64Array( 3 );
	const C = new Float64Array( 9 );
	const work = new Float64Array( 3 );

	dorm2r( 5, 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
	dorm2r( true, 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
	dorm2r( false, 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
	dorm2r( null, 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
	dorm2r( void 0, 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
	dorm2r( [], 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
	dorm2r( {}, 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
	dorm2r( ( x: number ): number => x, 'left', 'no-transpose', 3, 3, 3, A, 3, tau, C, 3, work ); // $ExpectError
}

